WITH flattened AS (SELECT id, host, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS key, value) SELECT CASE WHEN latency_ms >= 2314 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN level = 'ERROR' THEN 1 END), 0), 2) AS status_code_per_error, BIT_AND(latency_ms) AS latency_ms_bit_and, SUM(CASE WHEN key = 'trace' THEN latency_ms ELSE 0 END) AS trace_latency_ms FROM flattened GROUP BY CASE WHEN latency_ms >= 2314 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY trace_latency_ms NULLS FIRST
